const $=(s)=>document.querySelector(s);
const app=$('#app');
const state={draft:null,photo:null,inviteLink:null,inviteCase:null,tab:'text',session:false,admin:false};
const sample={category:'phone',asking_price:220000,offer_text:'URGENT SALE! iPhone 13, neat and original. Today only. Pay a deposit to reserve it now. Delivery only, no inspection. DM to purchase.',offer_url:''};
const icons={shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',folder:'<rect x="2" y="5" width="20" height="16" rx="2"/><path d="M2 9h20M7 5V3h5l2 2"/>',book:'<path d="M3 19V5a2 2 0 0 1 2-2h16v18H5a2 2 0 0 1-2-2Zm0 0a2 2 0 0 1 2-2h16"/>',check:'<path d="m4 12 5 5L20 6"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-7z"/>',lock:'<rect x="5" y="10" width="14" height="12" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',clipboard:'<rect x="5" y="4" width="14" height="18" rx="2"/><rect x="9" y="2" width="6" height="5" rx="1"/><path d="M9 12h6M9 16h6"/>',clock:'<circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/>',alert:'<path d="m12 2 10 19H2z"/><path d="M12 9v5m0 3h.01"/>',file:'<path d="M6 2h8l5 5v15H6zM14 2v5h5M9 13h7M9 17h7"/>',message:'<path d="M21 12a9 9 0 0 1-9 9 9 9 0 0 1-5-1.5L3 21l1.5-4A9 9 0 1 1 21 12Z"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 17v4h16v-4"/>',trash:'<path d="M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14M10 11v7m4-7v7"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',heart:'<path d="M20.8 4.6a5.6 5.6 0 0 0-8 0l-.8.8-.8-.8a5.6 5.6 0 0 0-8 8L12 22l8.8-9.4a5.6 5.6 0 0 0 0-8z"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-10h.01"/>',help:'<circle cx="12" cy="12" r="10"/><path d="M9 9a3 3 0 0 1 6 1c0 2-3 2-3 5m0 3h.01"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',chevron:'<path d="m9 18 6-6-6-6"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',download:'<path d="M12 2v14m-5-5 5 5 5-5M4 18v4h16v-4"/>',flag:'<path d="M5 2v20M5 4h14l-4 5 4 5H5"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>',mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 6 10 8 10-8"/>',device:'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M11 19h2"/>',users:'<path d="M16 20v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm13 10v-2a4 4 0 0 0-3-3.9M16 2.1a4 4 0 0 1 0 7.8"/>',refresh:'<path d="M20 11a8 8 0 0 0-14-5L3 9m0-6v6h6m-5 4a8 8 0 0 0 14 5l3-3m0 6v-6h-6"/>'};
function icon(name,sz=19){return `<svg aria-hidden="true" width="${sz}" height="${sz}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${icons[name]||icons.info}</svg>`}
const esc=(s='')=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const title=s=>s?String(s)[0].toUpperCase()+String(s).slice(1):'Offer';
const date=t=>new Date(t).toLocaleString('en-NG',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
const money=n=>n==null?'Not provided':'₦'+Number(n).toLocaleString('en-NG');
const a=(href,label,cl='')=>`<a href="${href}" data-nav class="${cl}">${label}</a>`;
const badge=(s)=>{const label={URGENT_CAUTION:'Heightened caution',IMPORTANT_GAPS:'Important gaps',INSUFFICIENT_INFORMATION:'Not yet established',PENDING:'Awaiting seller',RESPONDED:'Response received',DECLINED:'Seller declined',EXPIRED:'Expired',REVOKED:'Revoked'}[s]||s?.replaceAll('_',' ').toLowerCase()||'Unknown';const tone=s==='URGENT_CAUTION'?'badge-red':s==='IMPORTANT_GAPS'||s==='PENDING'?'badge-amber':s==='RESPONDED'?'badge-teal':'badge-gray';return `<span class="badge ${tone}">${esc(label)}</span>`};
async function request(url,method='GET',body){const opts={method,credentials:'same-origin',headers:{}};if(body!==undefined){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(body)}let res;try{res=await fetch(url,opts)}catch{throw Error('Cannot connect to the application server.')}let data;try{data=await res.json()}catch{throw Error('Unexpected server response.')}if(!res.ok)throw Error(data.error||`Request failed (${res.status})`);return data;}
let toastTimer;
function toast(msg,kind='success'){document.querySelectorAll('.toast').forEach(n=>n.remove());const el=document.createElement('div');el.className=`toast ${kind}`;el.role='status';el.textContent=msg;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),4800)}
function navigate(url){history.pushState({},'',url);state.inviteLink = url.includes('/invite')?state.inviteLink:null;render();window.scrollTo(0,0);}
function brand(){return `<a data-nav href="/" class="brand" aria-label="MABRIG PROVE home"><span class="brand-mark"><svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="#65e1c0" stroke-width="2" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m8 12 3 3 5-6" stroke="#fff"/></svg></span><span class="brand-copy"><b>MABRIG <span class="accent">PROVE</span></b><small>BY MABRIG TECHNOLOGIES</small></span></a>`}
function shell(content,active=''){return `<div class="app-shell"><header class="topbar">${brand()}<nav class="topnav" aria-label="Primary">${a('/','Home',active==='home'?'active':'')}${a('/cases','My checks',active==='cases'?'active':'')}${a('/how','How it works',active==='how'?'active':'')}${a('/help','Help & privacy',active==='help'?'active':'')}</nav><div class="head-actions"><span class="top-flag"><span class="dot"></span> PRIVATE BY DESIGN</span>${a('/check/new','Check an offer '+icon('arrow',14),'btn btn-dark btn-sm')}</div></header><main id="main">${content}</main><footer class="footer"><div class="container footer-inner"><span>© ${new Date().getFullYear()} MABRIG Technologies · Built to encourage evidence, not accusations.</span><div class="footer-links">${a('/help','Privacy & support')}${a('/how','About PROVE')}${a('/admin','Admin')}</div></div></footer><nav class="mobile-nav" aria-label="Mobile navigation">${a('/',icon('home')+'<span>Home</span>')}${a('/cases',icon('folder')+'<span>My checks</span>')}${a('/check/new',icon('search')+'<span>New check</span>')}${a('/help',icon('help')+'<span>Help</span>')}</nav></div>`}
function view(inner,active=''){app.innerHTML=shell(`<div class="container page">${inner}</div>`,active);}
function crumbs(parts){return `<nav class="breadcrumb" aria-label="Breadcrumb">${a('/','Home')}${parts.map(p=>`${icon('chevron',13)}${p.href?a(p.href,esc(p.name)):`<span>${esc(p.name)}</span>`}`).join('')}</nav>`}
function note(str,type='info'){return `<div class="note ${type==='warning'?'warning':''}">${icon(type==='warning'?'alert':'info',18)}<p>${str}</p></div>`}
function steps(){return `<div class="side-list"><div class="side-item"><span class="side-number">01</span><div><b>Share the offer</b><span>Paste the actual advert text, with optional supporting screenshots.</span></div></div><div class="side-item"><span class="side-number">02</span><div><b>Understand the gaps</b><span>Review warnings grounded in what you submitted, not made-up ratings.</span></div></div><div class="side-item"><span class="side-number">03</span><div><b>Request evidence</b><span>Invite the seller to respond voluntarily, then choose safer next steps.</span></div></div></div>`}
function home(){app.innerHTML=shell(`<div class="container page"><section class="hero"><div class="hero-left"><span class="eyebrow">${icon('shield',15)} A SMARTER WAY TO BUY ONLINE</span><h1>Before you trust it, <em>make it prove it.</em></h1><p>That online deal looks amazing. But what do you actually know? Check the offer, request specific proof, and make your next move with more clarity.</p><div class="hero-buttons">${a('/check/new','Check an offer '+icon('arrow',16),'btn btn-primary')}${a('/how','See how it works '+icon('eye',16),'btn btn-outline')}</div><div class="hero-assurance"><span>${icon('lock',14)} Private cases</span><span class="bullet"></span><span>No account needed</span><span class="bullet"></span><span>Evidence, not accusations</span></div></div><div class="hero-right"><div class="mockcard"><div class="mockhead"><div style="display:flex;align-items:center;gap:9px"><span class="mini-logo">${icon('search',18)}</span><div><h3>Offer assessment</h3><p class="mock-sub">Example: Online phone purchase</p></div></div><span class="demo-stamp">EXAMPLE</span></div><span class="mocktag">● Important questions remain</span><div class="mockrow"><b>⚠ Payment pressure identified</b><p>Offer mentions paying a deposit before inspection.</p></div><div class="mockrow"><b>◎ Ownership not established</b><p>An advert alone cannot confirm who owns the device.</p></div><div class="mockrow"><b>✓ A useful next step</b><p>Request an item-specific demonstration and independent inspection.</p></div><div class="mockcta">Request specific proof ${icon('arrow',12)}</div></div><div class="floatcard"><span class="flogo">${icon('shield',19)}</span><span><b>Clarity before commitment</b><small>You decide with better evidence.</small></span></div></div></section><section class="sections"><div class="section-heading"><div><span class="caps accent">YOUR PROOF-FIRST WORKFLOW</span><h2>Three steps to a smarter decision</h2></div><p>From a suspicious advert to a practical evidence checklist. You stay in control of the conversation.</p></div><div class="features"><article class="feature"><div class="ficon">${icon('search',22)}</div><h3>01. Inspect the offer</h3><p>Submit the advert text, link and optional screenshot. PROVE identifies observable warning signals and what is still unknown.</p></article><article class="feature"><div class="ficon">${icon('clipboard',22)}</div><h3>02. Ask for specific proof</h3><p>Build a tailored checklist, generate a private seller invitation and invite a voluntary response.</p></article><article class="feature"><div class="ficon">${icon('file',22)}</div><h3>03. Decide with clarity</h3><p>Compare buyer and seller statements, document missing evidence and plan independent verification before paying.</p></article></div><div class="lowerband"><div class="darkbanner"><div><span class="caps" style="color:#7de2cb">TRY A REAL WORKFLOW</span><h3>See how the proof process works.</h3><p>Run a synthetic sample check. No actual seller or personal data needed.</p></div><button class="btn btn-primary" data-action="demo">Try sample case ${icon('arrow',16)}</button></div><div class="finebanner"><span class="roundicon">${icon('lock',20)}</span><div><strong>A clear promise — not a false guarantee</strong><p>PROVE does not certify sellers, verify ownership or guarantee payments. This preview uses transparent local rules, not an external AI model or live marketplace search.</p></div></div></div></section></div>`,'home');}
function check(){view(`${crumbs([{name:'New check'}])}<div class="page-header"><span class="caps accent">START HERE</span><h1>Check an online offer</h1><p>Copy what the seller actually wrote. We'll identify observable signals and help you request more meaningful evidence.</p></div><div class="content-grid"><section class="card"><div class="stepper"><span class="done"></span><span></span><span></span></div><h2>Tell us about the offer</h2><p class="card-desc">Your first private assessment takes only a few steps. No registration required.</p><form id="offer-form"><div class="input-tabs"><button type="button" class="tab ${state.tab==='text'?'active':''}" data-action="tab" data-value="text">${icon('clipboard',14)} Paste advert</button><button type="button" class="tab ${state.tab==='screenshot'?'active':''}" data-action="tab" data-value="screenshot">${icon('upload',14)} Screenshot</button><button type="button" class="tab ${state.tab==='link'?'active':''}" data-action="tab" data-value="link">${icon('search',14)} Link</button></div><label class="field"><span>Item category *</span><select name="category" required><option value="phone" ${state.draft?.category==='phone'?'selected':''}>Phone / Smartphone</option><option value="laptop" ${state.draft?.category==='laptop'?'selected':''}>Laptop / Computer</option><option value="other" ${state.draft?.category==='other'?'selected':''}>Other product</option></select></label><label class="field"><span>Advert text or seller's description *</span><textarea name="offer_text" minlength="15" maxlength="5000" required placeholder="Example: Selling my iPhone 13. Pay a deposit today before I can deliver it...">${esc(state.draft?.offer_text||'')}</textarea><small>At least 15 characters. Screenshots are stored as supporting attachments; automatic image text reading is not enabled yet.</small></label><div class="field-row"><label class="field"><span>Asking price in ₦ (optional)</span><input name="asking_price" type="number" min="0" max="10000000000" value="${esc(state.draft?.asking_price||'')}" placeholder="e.g. 220000"></label><label class="field"><span>Offer URL (optional)</span><input name="offer_url" type="url" maxlength="600" value="${esc(state.draft?.offer_url||'')}" placeholder="https://..."></label></div><div class="upload"><p>${icon('upload',19)} <strong>Add an optional screenshot</strong></p><p>JPG, PNG or WebP, max 2MB after privacy-safe processing.</p><input type="file" id="evidence-file" accept="image/png,image/jpeg,image/webp" aria-label="Attach offer screenshot"><p id="selected-file" class="micro">${state.photo?esc(state.photo.name):'No file selected'}</p></div><div class="form-actions"><span class="micro muted" style="margin-right:auto">No external website will be fetched.</span><button class="btn btn-primary" type="submit">Review my information ${icon('arrow',16)}</button></div></form></section><aside><div class="card"><h3>What happens next?</h3><p class="card-desc">A simple and explainable process.</p>${steps()}</div><div class="card">${note('Never paste an NIN, BVN, bank PIN, account password, government ID or someone else’s private correspondence. You can edit text before submission.','warning')}<span class="micro muted">Private guest cases are stored for up to 30 days in this local MVP.</span></div></aside></div>`);}
function review(){if(!state.draft)return navigate('/check/new');const txt=state.draft.offer_text;const possible=[...new Set([(txt.match(/(?:\+?234|0)[789]\d{9}/g)||[]).length?'Phone number':null,(txt.match(/[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}/g)||[]).length?'Email address':null].filter(Boolean))];view(`${crumbs([{name:'New check',href:'/check/new'},{name:'Review & consent'}])}<div class="page-header"><span class="caps accent">STEP 2 OF 3</span><h1>Review before you submit</h1><p>You're in control of the information stored in this case. Consider removing any personal or sensitive details.</p></div><div class="content-grid"><section class="card"><div class="stepper"><span class="done"></span><span class="done"></span><span></span></div>${note(possible.length?`We noticed possible: <b>${possible.join(', ')}</b>. Automatic redaction can help, but please inspect the entire description.`:'We did not detect common phone or email patterns. Please still inspect the text for sensitive personal information.')}<form id="review-form"><label class="field"><span>What will be analyzed</span><textarea name="offer_text" minlength="15" maxlength="5000" required>${esc(txt)}</textarea></label><div class="checkline"><input type="checkbox" name="redact" id="redact" checked><label for="redact">Mask common phone numbers, emails and 10-digit numbers where recognized. Review the result yourself because automated masking is imperfect.</label></div><div class="checkline"><input type="checkbox" name="consent" id="consent" required><label for="consent">I understand this is an informational tool, not a seller certification, and I have the right to submit the information provided.</label></div>${note('No site is scraped or contacted. This preview runs transparent local rules; an external AI provider is not connected.','warning')}<div class="form-actions">${a('/check/new','Back to edit','btn btn-outline')}<button class="btn btn-primary" type="submit">Analyze safely ${icon('arrow',16)}</button></div></form></section><aside class="card"><h3>Your input summary</h3><div class="info-tile"><small>CATEGORY</small><b>${esc(title(state.draft.category))}</b></div><div class="info-tile" style="margin-top:11px"><small>ASKING PRICE</small><b>${money(state.draft.asking_price)}</b></div><div class="info-tile" style="margin-top:11px"><small>SCREENSHOT</small><b>${state.photo?esc(state.photo.name):'None added'}</b></div><div class="tinydiv"></div><p class="micro muted">By proceeding you accept that your private guest case will be stored locally and automatically expire after 30 days unless you delete it earlier.</p></aside></div>`);}
function caseNav(id,selected){const sections=[['/check/'+id,'Overview','search'],['/check/'+id+'/request','Request proof','clipboard'],['/check/'+id+'/invite','Seller invitation','message'],['/check/'+id+'/compare','Compare evidence','eye'],['/check/'+id+'/decision','Decision gate','check'],['/check/'+id+'/report','Decision report','file']];return `<aside class="side-nav"><div class="smalllabel caps">CASE WORKSPACE</div>${sections.map(([url,label,ico])=>a(url,icon(ico,17)+' '+label,selected===url?'selected':'')).join('')}</aside>`}
function caseFrame(c,selected,content){if(selected.endsWith('/report'))content+=`<section class="card"><h2>Share a general safety reminder</h2><p class="micro muted">This tip never includes a seller, advert, private case ID, submitted answer or accusation.</p><button class="btn btn-outline" data-action="share-safety" data-id="${esc(c.id)}">${icon('message',16)} Share safety tip</button><div class="tinydiv"></div>${a('/check/'+c.id+'/decision','Update my decision gate','btn btn-primary')}</section>`;view(`${crumbs([{name:'My checks',href:'/cases'},{name:'Offer '+c.id.slice(-7)}])}<div class="case-layout">${caseNav(c.id,selected)}<div class="panel-stack">${content}</div></div>`,'cases')}
function analysisPage(c){const s=c.assessment,price=money(c.asking_price);const signals=s.signals.length?s.signals.map(x=>`<div class="signal"><div class="symbol">${icon('alert',17)}</div><div><strong>${esc(x.title)}</strong><p>${esc(x.detail)}</p><span class="micro muted">From your submitted offer text</span></div></div>`).join(''):'<p class="muted micro">No specific rule-based warning phrase was found. This does <strong>not</strong> mean the offer or seller is safe.</p>';
 caseFrame(c,`/check/${c.id}`,`<section class="card"><div class="case-head"><div><span class="caps accent">YOUR PRIVATE CASE</span><h1>${esc(title(c.category))} offer assessment</h1><p>Created ${date(c.created_at)} · Automatically expires ${date(c.expires_at)}</p></div>${badge(s.attention)}</div><div class="info-grid"><div class="info-tile"><small>ASKING PRICE</small><b>${price}</b></div><div class="info-tile"><small>REVIEW ENGINE</small><b>Local rules</b></div><div class="info-tile"><small>SELLER INVITATION</small><b>${c.invite?esc(title(c.invite.status.toLowerCase())):'Not sent'}</b></div></div></section><section class="card"><div class="card-header"><div><h2>Observed warning signals</h2><p class="card-desc" style="margin:0">Only rules matched against the text you submitted</p></div>${badge(s.attention)}</div>${signals}</section><section class="card"><h2>Claims found in the advert</h2><p class="card-desc">These are statements in the submission—not independently verified facts.</p><div class="claim-list">${s.claims.map(q=>`<div class="claim-item"><blockquote>“${esc(q.excerpt)}”</blockquote><small>${esc(q.evidence_status)}</small></div>`).join('')}</div></section><section class="card"><h2>Questions that still matter</h2><ul class="bullet-list">${s.unknowns.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="tinydiv"></div>${note(esc(s.limits),'warning')}<div class="form-actions">${a('/check/'+c.id+'/decision','Complete decision gate','btn btn-outline')}${a('/check/'+c.id+'/request','Request specific proof '+icon('arrow',14),'btn btn-primary')}</div></section><section class="card"><h3>Manage this private case</h3><p class="card-desc">You can remove the case and its attachments immediately.</p><button class="btn btn-danger btn-sm" data-action="delete-case" data-id="${esc(c.id)}">${icon('trash',15)} Delete this case</button></section>`)}
function questionsEditor(c){const questions=c.assessment.questions;caseFrame(c,`/check/${c.id}/request`,`<section class="card"><div class="stepper"><span class="done"></span><span class="done"></span><span></span></div><span class="caps accent">CREATE A PROOF REQUEST</span><h2 style="font-size:26px;margin:9px 0">Ask the right questions</h2><p class="card-desc">Edit the suggested questions to match the specific offer. A random challenge code will be generated when you create the link.</p>${note('The seller can choose to respond or decline. Do not request NIN, BVN, passports, passwords or other sensitive identity information.')}<form id="invite-form" data-case="${esc(c.id)}">${questions.map((q,i)=>`<label class="field"><span>Question ${i+1}</span><textarea name="question" maxlength="250" rows="2" style="min-height:85px">${esc(q)}</textarea></label>`).join('')}<div class="form-actions">${a('/check/'+c.id,'Back to analysis','btn btn-outline')}<button type="submit" class="btn btn-primary">Generate private link ${icon('arrow',16)}</button></div></form></section><section class="card"><h3>Seller privacy expectations</h3><ul class="bullet-list"><li>The seller sees only the questions and a random challenge code.</li><li>The seller is not shown your private advert analysis or contact details.</li><li>A seller response does not establish ownership or safety.</li><li>The link expires after 72 hours and can be revoked.</li></ul></section>`)}
function invitePage(c){const link=state.inviteCase===c.id?state.inviteLink:null;const invite=c.invite;
 caseFrame(c,`/check/${c.id}/invite`,`<section class="card"><span class="caps accent">SHARE A REQUEST</span><h2 style="font-size:26px;margin:9px 0">Your seller invitation</h2><p class="card-desc">You choose whether and how to contact the seller. MABRIG PROVE will never contact a seller on your behalf.</p>${invite?`<div class="challenge"><span class="caps accent">CHALLENGE CODE</span><div class="challenge-code">${esc(invite.challenge_code)}</div><p class="micro muted">${badge(invite.status)} &nbsp; Expires ${date(invite.expires_at)}</p></div>`:note('No invitation has been generated for this case yet.')}
 ${link?`<div style="margin-top:20px"><label class="field"><span>Private seller link — keep it out of public posts</span><input type="text" readonly id="invite-url" value="${esc(link)}"></label><div class="form-actions" style="justify-content:flex-start"><button class="btn btn-primary" data-action="copy-link">${icon('copy',15)} Copy invitation</button><button class="btn btn-outline" data-action="share-whatsapp">${icon('message',15)} Share via WhatsApp</button></div></div>`:invite?.status==='PENDING'?`${note('For security, existing invitation tokens are not retrievable after you leave this page. Generate a replacement only when you need a fresh link. The previous link will be revoked.','warning')}<button class="btn btn-primary" data-action="renew-invite" data-id="${esc(c.id)}">Generate replacement link</button>`:a(`/check/${c.id}/request`,'Create a proof request '+icon('arrow',16),'btn btn-primary')}
 ${invite&&invite.status==='PENDING'?`<div class="tinydiv"></div><button class="btn btn-danger btn-sm" data-action="revoke-invite" data-id="${esc(c.id)}">${icon('trash',14)} Revoke invitation</button>`:''}${invite?.status==='RESPONDED'?`<div class="tinydiv"></div>${note('A response has been received. Compare it with the original offer; it has not been independently checked.')}${a('/check/'+c.id+'/compare','Compare submitted answers','btn btn-primary')}`:''}${invite?.status==='DECLINED'?note('The seller declined voluntarily. Declining is not evidence of wrongdoing.'):''}</section><section class="card"><h3>What the seller sees</h3><div class="mini-steps">${(invite?.questions||c.assessment.questions).slice(0,5).map((_,i)=>`<span class="step-label">Question ${i+1}</span>`).join('')}</div><ul class="bullet-list">${(invite?.questions||c.assessment.questions).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`)}
function comparePage(c){const invite=c.invite;const answers=c.response?.answers||[];caseFrame(c,`/check/${c.id}/compare`,`<section class="card"><span class="caps accent">BUYER VS. SELLER STATEMENTS</span><h2 style="font-size:26px;margin:9px 0">Compare the response</h2><p class="card-desc">Seller-submitted descriptions are not external corroboration. You decide whether an independent inspection is needed.</p>${!invite?note('Create a proof request to invite a response.'):!c.response?note(`Invitation status: <b>${esc(invite.status)}</b>. No seller answers have been submitted yet.`,'warning'):`<div class="challenge"><strong>${icon('check',16)} Seller response received</strong><p class="micro muted" style="margin-bottom:0">Submitted ${date(c.response.created_at)} · Not independently verified</p></div>${invite.questions.map((q,i)=>`<div class="answer-pair"><b>${i+1}. ${esc(q)}</b><p>Seller-submitted information</p><div class="submitted">${answers[i]?esc(answers[i]):'<em>Not answered</em>'}</div><p>${answers[i]?'This is a seller statement, not proof of truth.':'No evidence is available for this request.'}</p></div>`).join('')}`}${note('A challenge code or submitted media can be fabricated or reused. Never claim that it proves identity, ownership or transaction fulfillment.','warning')}<div class="form-actions">${a('/check/'+c.id+'/invite','Invitation status','btn btn-outline')}${a('/check/'+c.id+'/decision','Review next steps '+icon('arrow',14),'btn btn-primary')}</div></section>`)}
function decisionPage(c){
 const g=c.gate;
 const options=[['NOT_DONE','Not checked'],['PLANNED','Planned'],['DONE','I checked this'],['UNAVAILABLE','Unavailable']];
 const rows=g.items.map(item=>`<form class="gate-item" data-step="${esc(item.key)}" data-case="${esc(c.id)}"><div class="gate-head"><span class="gate-icon">${item.status==='DONE'?icon('check',18):icon('clipboard',18)}</span><div><h3>${esc(item.label)} ${item.critical?'<span class="gate-required">important</span>':''}</h3><p class="micro muted">${esc(item.detail)}</p></div></div><div class="gate-controls"><label class="field"><span>My status</span><select name="state">${options.map(([v,l])=>`<option value="${v}" ${v===item.status?'selected':''}>${l}</option>`).join('')}</select></label><label class="field gate-note"><span>Private notes (optional)</span><input name="note" maxlength="500" value="${esc(item.note)}" placeholder="What did you check or discover?"></label><button class="btn btn-outline btn-sm" type="submit">Save step</button></div></form>`).join('');
 const selected=g.decision?.choice||'';
 const decisions=[['PAUSE','Pause and gather more evidence'],['WALK_AWAY','Walk away from this deal'],['PROCEED_WITH_PRECAUTIONS','Consider proceeding with precautions']];
 caseFrame(c,`/check/${c.id}/decision`,`<section class="card"><span class="caps accent">BUYER-CONTROLLED SAFETY CHECKS</span><h2 style="font-size:26px;margin:9px 0">Your decision gate</h2><p class="card-desc">Take five concrete steps before sending money. Your checks are self-recorded and are <strong>not</strong> independent verification by PROVE.</p><div class="gate-summary"><strong>${g.completed} of ${g.total} steps marked checked</strong><span>${g.critical_pending.length} important steps not marked checked</span></div>${g.critical_pending.length?note('Important questions remain. Never interpret a completed checklist as a guarantee of safety.','warning'):note('You marked all important steps complete. These are your own statements, not independently verified results.')}</section><section class="card"><h2>My verification checklist</h2><p class="micro muted">Do not submit IDs, account passwords, bank numbers or other sensitive details.</p>${rows}</section><section class="card"><span class="caps accent">YOUR CHOICE</span><h2>Record a private decision</h2><p class="card-desc">Choose the action that matches your own judgment. You can update it later.</p><form id="decision-form" data-case="${esc(c.id)}"><label class="field"><span>Decision</span><select name="choice" required><option value="">Choose next step</option>${decisions.map(([v,l])=>`<option value="${v}" ${selected===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field"><span>My reason (optional)</span><textarea name="note" maxlength="500" rows="3" placeholder="Write your decision without sharing private identifying information">${esc(g.decision?.note||'')}</textarea></label><label class="checkline"><input type="checkbox" name="acknowledged" required><span>I understand MABRIG PROVE has not independently verified this seller, item or transaction.</span></label><div class="form-actions"><button type="submit" class="btn btn-primary">Record private decision</button>${a('/check/'+c.id+'/report','Read decision report','btn btn-outline')}</div></form>${g.decision?`<div class="tinydiv"></div>${note('Your last recorded choice: <b>'+esc(decisions.find(x=>x[0]===g.decision.choice)?.[1]||'Unknown')+'</b>. It is your decision, not a recommendation by PROVE.')}`:''}</section>`);
}
function shareSafetyTip(c){const category=c.category==='phone'?'phone':c.category==='laptop'?'laptop':'online item';return `Before you pay for a ${category} online, demand real proof and arrange independent inspection. An advert, screenshot or seller video alone cannot establish ownership or guarantee delivery. Check first with MABRIG PROVE — https://www.mabrigkorie.org (general safety advice, not an allegation about anyone).`}
function reportPage(c,r){caseFrame(c,`/check/${c.id}/report`,`<section class="report-head"><span class="caps" style="color:#87e5cc">PRIVATE DECISION REPORT</span><h2 style="margin:9px 0">${esc(r.title)}</h2><p>${date(r.created_at)} · Case reference ${esc(c.id.slice(-12))}</p></section><section class="card"><div class="card-header"><div><h2>Where things stand</h2><p class="card-desc" style="margin:0">Evidence quality, not a seller score</p></div>${badge(r.attention)}</div><div class="callout"><strong>${icon('alert',16)} ${esc(r.summary)}</strong></div><div class="tinydiv"></div><h3>Seller participation</h3><p class="muted micro">${esc(r.seller_provided)}</p></section><section class="card"><h2>Observed issues</h2>${r.findings.length?r.findings.map(x=>`<div class="signal"><span class="symbol">${icon('alert',16)}</span><div><strong>${esc(x.title)}</strong><p>${esc(x.detail)}</p></div></div>`).join(''):'<p class="muted micro">No predefined phrase-based warning was matched. This is not an endorsement.</p>'}<div class="tinydiv"></div><h2>What remains unknown</h2><ul class="bullet-list">${r.unknowns.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="card"><h2>Recommended next actions</h2><ul class="bullet-list">${r.next_steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${note(esc(r.limitations),'warning')}<div class="form-actions no-print"><button class="btn btn-outline" data-action="print">${icon('download',16)} Print or save PDF</button><button class="btn btn-primary" data-action="export-json" data-id="${esc(c.id)}">${icon('download',16)} Export private report</button></div></section>`)}
function casesPage(cases){view(`${crumbs([{name:'My checks'}])}<div class="page-header"><span class="caps accent">YOUR PRIVATE WORKSPACE</span><h1>My offer checks</h1><p>These cases are linked to this browser's private guest session. If you clear your browser cookies or use a different device, they will not be accessible.</p></div><div class="card"><div class="card-header"><div><h2>Recent cases</h2><p class="card-desc" style="margin:0">${cases.length} saved here · Automatically expire after 30 days</p></div>${a('/check/new',icon('search',15)+' New check','btn btn-primary btn-sm')}</div>${cases.length?`<div class="case-list">${cases.map(c=>`<div class="case-list-item"><div>${badge(c.assessment.attention)} <span class="micro muted" style="margin-left:8px">${date(c.created_at)}</span><h3>${esc(title(c.category))} offer · ${money(c.asking_price)}</h3><p>${esc(c.offer_text.slice(0,125))}${c.offer_text.length>125?'…':''}</p></div>${a('/check/'+c.id,'Open '+icon('arrow',13),'btn btn-outline btn-sm')}</div>`).join('')}</div>`:`<div class="empty"><div class="giant">${icon('folder',46)}</div><h3>No checks yet</h3><p>Start with a real offer or explore the workflow using a fictional example.</p><div class="form-actions" style="justify-content:center">${a('/check/new','Start a new check','btn btn-primary')}<button class="btn btn-outline" data-action="demo">Try sample</button></div></div>`}</div><div style="margin-top:17px">${note('Case data is stored in the local app backend, not on an AI model. You can delete your entire guest session, including cases and attachments, using the control below.')}</div><button data-action="delete-session" class="btn btn-danger btn-sm">${icon('trash',15)} Delete all my private data</button>`,'cases');}
function sellerIntro(token,p){view(`${crumbs([{name:'Seller proof request'}])}<div class="page-header"><span class="caps accent">VOLUNTARY EVIDENCE REQUEST</span><h1>Someone has asked for more information</h1><p>A prospective buyer wants to understand an online offer better. You can respond, decline or report this request.</p></div><div class="content-grid"><section class="card"><div class="card-header"><h2>Review the request</h2>${badge(p.status)}</div><div class="challenge"><span class="caps accent">CHALLENGE CODE</span><div class="challenge-code">${esc(p.challenge_code)}</div><p class="micro muted" style="margin:0">Expires ${date(p.expires_at)}</p></div><h3 style="margin-top:24px">Information requested</h3><ul class="bullet-list">${p.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul><div class="tinydiv"></div>${note('Your response will be visible to the requester. You are not being asked to prove your identity, upload an ID or reveal private account details. Do not disclose passwords, bank information or other sensitive data.')}<div class="form-actions" style="justify-content:flex-start">${p.status==='PENDING'?a('/prove/'+token+'/respond','Respond voluntarily '+icon('arrow',16),'btn btn-primary')+'<button class="btn btn-outline" data-action="decline" data-token="'+esc(token)+'">Decline politely</button>':'<span class="muted micro">This request is no longer accepting responses.</span>'}</div></section><aside><div class="card"><h3>Privacy comes first</h3><p class="card-desc">The requester never gets to see your account credentials. In this MVP, your written answers are shared only within their private case.</p>${steps()}</div><div class="card"><h3>Concerned about this request?</h3><p class="muted micro">Misleading or intrusive proof requests can be reported without submitting an answer.</p><button class="btn btn-outline btn-sm" data-action="report-seller" data-token="${esc(token)}">${icon('flag',15)} Report request</button></div></aside></div>`);}
function sellerRespond(token,p){if(p.status!=='PENDING')return sellerIntro(token,p);view(`${crumbs([{name:'Proof request',href:'/prove/'+token},{name:'Submit a response'}])}<div class="page-header"><span class="caps accent">SELLER RESPONSE</span><h1>Share what you choose to disclose</h1><p>This response is voluntary and visible to the case requester. You can leave a question unanswered.</p></div><div class="content-grid"><section class="card"><div class="challenge"><b>Challenge code: <span style="letter-spacing:.14em">${esc(p.challenge_code)}</span></b><p class="micro muted" style="margin:6px 0 0">Mention the code when providing a demonstration outside this application. It does not prove legal ownership.</p></div><form id="seller-form" data-token="${esc(token)}" style="margin-top:20px">${p.questions.map((q,i)=>`<div class="proof-question"><label for="answer-${i}">${i+1}. ${esc(q)}</label><textarea id="answer-${i}" name="answer" maxlength="1500" placeholder="Your response (optional)"></textarea></div>`).join('')}<label class="checkline"><input type="checkbox" name="consent" required><span>I voluntarily agree to share my submitted answers with the requester. I understand this is not an identity or ownership certification.</span></label><div class="form-actions">${a('/prove/'+token,'Back','btn btn-outline')}<button type="submit" class="btn btn-primary">Submit response ${icon('arrow',16)}</button></div></form></section><aside class="card"><h3>Before you respond</h3>${note('Do not post your NIN, BVN, bank details, passwords, full IMEI or identity card. If you cannot answer, you may leave it blank or decline the request.','warning')}<p class="micro muted">This pilot accepts written responses only. Evidence media and automatic forgery detection will be added only after security and privacy review.</p></aside></div>`);}
function how(){view(`${crumbs([{name:'How it works'}])}<div class="page-header"><span class="caps accent">THE PROOF-FIRST APPROACH</span><h1>What PROVE can — and cannot — establish</h1><p>Our goal is to help buyers make better-informed choices, not to give sellers a misleading badge or pretend AI can guarantee a safe transaction.</p></div><div class="features"><div class="feature"><div class="ficon">${icon('search',22)}</div><h3>Understand the claim</h3><p>We'll examine exactly what you submit. This local MVP uses transparent phrase-matching rules, not unverified external intelligence.</p></div><div class="feature"><div class="ficon">${icon('clipboard',22)}</div><h3>Ask for relevant details</h3><p>Generate a time-limited request with specific questions. The other party can decline without being accused of wrongdoing.</p></div><div class="feature"><div class="ficon">${icon('shield',22)}</div><h3>Confirm independently</h3><p>Compare responses and choose a safer step such as meeting in person or consulting an independent inspector.</p></div></div><div class="lowerband"><div class="card"><h2>Important limitations</h2><ul class="bullet-list"><li>Matching a challenge code does not establish item ownership or honesty.</li><li>Photos, documents and written claims can be fabricated or outdated.</li><li>The current engine does not fetch seller links, verify phone numbers or inspect public records.</li><li>The result is not financial, legal or law-enforcement advice.</li></ul></div><div class="card"><h2>Built for trust through clarity</h2><p class="muted micro">Every indicator is linked to the information that triggered it. No false confidence percentages, fictitious testimonials or reputation scores are displayed.</p><button class="btn btn-primary" data-action="demo">Try a fictional check ${icon('arrow',16)}</button></div></div>`,'how');}
function help(){view(`${crumbs([{name:'Help & privacy'}])}<div class="page-header"><span class="caps accent">SUPPORT CENTER</span><h1>Your privacy matters</h1><p>Find answers to common questions and learn what this development version does with your information.</p></div><div class="content-grid"><section class="card"><h2>Frequently asked questions</h2><div class="faq"><h3>Does PROVE guarantee a seller is safe?</h3><p>No. It identifies some observable signals, compares voluntary answers and explains what cannot be independently established.</p></div><div class="faq"><h3>Will you contact the seller for me?</h3><p>No. You decide whether and where to share the private invitation link. Never post it publicly.</p></div><div class="faq"><h3>Can I delete my data?</h3><p>Yes. Delete an individual case or erase the guest session from My checks. Cases expire automatically after 30 days.</p></div><div class="faq"><h3>Is this app connected to live AI or payment providers?</h3><p>Not in this local MVP. The engine uses an explainable rule catalogue. No payment collection or bank verification is available.</p></div><div class="faq"><h3>How is a screenshot handled?</h3><p>If you choose to upload one, the browser redraws it to remove common image metadata and privately attaches it to the case. It is not automatically analyzed. You must provide offer text.</p></div><div class="faq"><h3>Can I log in on another device and find my cases?</h3><p>No. These cases belong to a browser-specific private guest session. Verified accounts and syncing are not yet available.</p></div></section><aside class="card"><h3>Need further help?</h3><p class="muted micro">This MVP does not yet have an automated ticket inbox. For product enquiries, visit MABRIG Technologies.</p><a class="btn btn-outline btn-full" href="https://www.mabrigkorie.org" target="_blank" rel="noopener noreferrer">${icon('help',16)} MABRIG Technologies</a><div class="tinydiv"></div>${note('Avoid sharing sensitive personal information with any support channel. Report a harmful seller invitation through the reporting button on that invitation.','warning')}</aside></div>`,'help')}
async function adminPage(){const cfg=await request('/api/health');if(!cfg.admin_configured){view(`${crumbs([{name:'Administration'}])}<div class="page-header"><h1>Safety operations console</h1><p>Reserved for authorized owner access.</p></div><div class="card" style="max-width:690px">${note('Administrative login is disabled by default. Configure an owner secret for local testing; production access must use a dedicated identity provider and multi-factor authentication.','warning')}<p class="muted micro">No administrator dashboard is accessible to public visitors. This is a deliberate safety gate.</p></div>`);return}let overview;try{overview=await request('/api/admin/overview')}catch{}if(!overview){view(`${crumbs([{name:'Administration'}])}<div class="page-header"><h1>Administrator access</h1><p>Local development access only. MFA is required before public release.</p></div><div class="card" style="max-width:510px"><form id="admin-login"><label class="field"><span>Admin password</span><input type="password" name="password" required autocomplete="current-password"></label><button class="btn btn-primary" type="submit">Sign in to preview console</button></form></div>`);return}const reports=await request('/api/admin/reports');view(`${crumbs([{name:'Administration'}])}<div class="page-header"><h1>Safety operations</h1><p>Local preview. No external integrations or user identity verification are enabled.</p></div><div class="info-grid"><div class="card"><span class="caps muted">PRIVATE CASES</span><h1>${overview.counts.cases}</h1></div><div class="card"><span class="caps muted">INVITATIONS</span><h1>${overview.counts.invites}</h1></div><div class="card"><span class="caps muted">OPEN ABUSE REPORTS</span><h1>${overview.counts.abuse}</h1></div></div><div class="card" style="margin-top:20px"><h2>Safety reports</h2>${reports.reports.length?reports.reports.map(x=>`<div class="signal"><div><b>${esc(x.role.toUpperCase())} · ${date(x.created_at)} · ${esc(x.status)}</b><p>${esc(x.reason)}</p>${x.status==='OPEN'?`<button class="btn btn-outline btn-sm" data-action="resolve-report" data-id="${esc(x.id)}">Mark resolved</button>`:''}</div></div>`).join(''):'<p class="muted micro">No reports submitted.</p>'}</div>`)}
async function load(){const p=location.pathname;
 if(p==='/')return home();if(p==='/check/new')return check();if(p==='/check/review')return review();if(p==='/how')return how();if(p==='/help')return help();if(p==='/admin')return adminPage();
 if(p==='/cases'){const x=await request('/api/cases');return casesPage(x.cases)}
 const seller=p.match(/^\/prove\/([A-Za-z0-9_-]+)(?:\/(respond))?$/);if(seller){const info=await request('/api/proof/'+seller[1]);return seller[2]?sellerRespond(seller[1],info.proof):sellerIntro(seller[1],info.proof)}
 const cm=p.match(/^\/check\/([^/]+)(?:\/(request|invite|compare|decision|report))?$/);if(cm){const x=await request('/api/cases/'+encodeURIComponent(cm[1]));const c=x.case;switch(cm[2]){case 'request':return questionsEditor(c);case 'invite':return invitePage(c);case 'compare':return comparePage(c);case 'decision':return decisionPage(c);case 'report':{const rr=await request('/api/cases/'+c.id+'/report');return reportPage(c,rr.report)}default:return analysisPage(c)}}
 view(`<div class="empty"><h1>Page not found</h1>${a('/','Return home','btn btn-primary')}</div>`)}
let renderVersion=0;
async function render(){const version=++renderVersion;app.innerHTML='<div class="startup"><div class="spinner"></div><p>Loading your private workspace…</p></div>';try{const p=location.pathname;if(!p.startsWith('/prove/')){const session=await request('/api/session');if(!session.active)await request('/api/session','POST');state.session=true}if(version!==renderVersion)return;await load();}catch(e){if(version!==renderVersion)return;view(`<div class="card" style="max-width:680px;margin:auto"><h2>Something needs attention</h2><p class="muted">${esc(e.message)}</p>${a('/','Go back home','btn btn-outline')}</div>`);toast(e.message,'error')}}
async function safeImage(file){if(!file)return null;if(!/^image\/(jpeg|png|webp)$/.test(file.type))throw Error('Choose a JPEG, PNG or WebP image.');if(file.size>8*1024*1024)throw Error('Original image must be under 8MB.');const im=await createImageBitmap(file);const maxEdge=1400,ratio=Math.min(1,maxEdge/Math.max(im.width,im.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(im.width*ratio));canvas.height=Math.max(1,Math.round(im.height*ratio));canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);im.close?.();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.78));if(!blob||blob.size>2*1024*1024)throw Error('Processed image is larger than 2MB. Use a smaller image.');const base64=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(Error('Could not read image.'));r.readAsDataURL(blob)});return {data:base64,mime:'image/jpeg'}}
async function submitOffer(){const b=state.draft;if(!b)throw Error('Review an offer first.');const x=await request('/api/cases','POST',b);const c=x.case;let evidenceWarning='';if(state.photo){try{const processed=await safeImage(state.photo);await request('/api/cases/'+c.id+'/evidence','POST',processed)}catch(e){evidenceWarning=' Case created, but the screenshot could not be attached: '+e.message}}state.draft=null;state.photo=null;toast('Private check created.'+evidenceWarning,evidenceWarning?'error':'success');navigate('/check/'+c.id)}
async function createInvite(caseId,questions){const r=await request('/api/cases/'+caseId+'/invite','POST',questions?{questions}:{});state.inviteCase=caseId;state.inviteLink=location.origin+'/prove/'+r.invite.token;navigate('/check/'+caseId+'/invite');toast('Invitation generated. Copy the private link before leaving this page.');}
async function demo(){const x=await request('/api/cases','POST',sample);navigate('/check/'+x.case.id);toast('Fictional sample created. Explore the full workflow.');}
function downloadObject(filename,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const el=document.createElement('a');el.href=url;el.download=filename;document.body.append(el);el.click();el.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(target){e.preventDefault();const action=target.dataset.action;const caseId=target.dataset.id,token=target.dataset.token;try{
 if(action==='tab'){state.tab=target.dataset.value;document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t===target));if(state.tab==='screenshot')$('#evidence-file')?.focus();if(state.tab==='link')document.querySelector('[name="offer_url"]')?.focus();return}
 if(action==='demo')return await demo();
 if(action==='share-safety'){const response=await request('/api/cases/'+caseId);const tip=shareSafetyTip(response.case);if(navigator.share)await navigator.share({title:'MABRIG PROVE safety tip',text:tip});else if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(tip);toast('Safety tip copied without case or seller details.')}else{window.prompt('Copy this general safety tip:',tip)}return}
 if(action==='delete-case'){if(!confirm('Delete this case and all its evidence permanently?'))return;await request('/api/cases/'+caseId,'DELETE');navigate('/cases');return toast('Case and evidence deleted.')}
 if(action==='delete-session'){if(!confirm('Delete your entire guest session and every case in it? This cannot be undone.'))return;await request('/api/session','DELETE');state.session=false;navigate('/');return toast('Your private session was erased.')}
 if(action==='copy-link'){const value=$('#invite-url')?.value;if(!value)throw Error('No invitation link available.');if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(value);else {$('#invite-url').select();document.execCommand('copy')}return toast('Private invitation copied.')}
 if(action==='share-whatsapp'){const value=$('#invite-url')?.value;if(!value)throw Error('No invitation link available.');window.open('https://wa.me/?text='+encodeURIComponent('Please review this voluntary proof request about the advertised item: '+value),'_blank','noopener,noreferrer');return}
 if(action==='renew-invite')return await createInvite(caseId);
 if(action==='revoke-invite'){if(!confirm('Revoke the active seller invitation?'))return;await request('/api/cases/'+caseId+'/invite/revoke','POST',{});state.inviteLink=null;await render();return toast('Invitation revoked.')}
 if(action==='decline'){if(!confirm('Decline this optional request?'))return;await request('/api/proof/'+token+'/decline','POST',{});await render();return toast('You declined voluntarily. No negative judgment is made.')}
 if(action==='report-seller'){const reason=prompt('Describe what is concerning about this proof request (minimum 8 characters):');if(reason===null)return;await request('/api/proof/'+token+'/report','POST',{reason});return toast('Your concern was submitted for review.')}
 if(action==='print'){window.print();return}
 if(action==='export-json'){const rr=await request('/api/cases/'+caseId+'/report');downloadObject('MABRIG-PROVE-private-report.json',rr.report);return}
 if(action==='resolve-report'){await request('/api/admin/reports/'+caseId+'/resolve','POST',{});await render();return toast('Report marked resolved.')}
 }catch(err){toast(err.message,'error')}return}
 const link=e.target.closest('a[data-nav]');if(link && !e.ctrlKey&&!e.metaKey&&!e.shiftKey&&e.button===0){e.preventDefault();navigate(link.getAttribute('href'))}
});
document.addEventListener('change',e=>{if(e.target.id==='evidence-file'){state.photo=e.target.files?.[0]||null;const el=$('#selected-file');if(el)el.textContent=state.photo?`${state.photo.name} (${(state.photo.size/1024).toFixed(0)} KB)`:'No file selected'}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['offer-form','review-form','invite-form','seller-form','admin-login','decision-form'].includes(form.id)&&!form.classList.contains('gate-item'))return;e.preventDefault();const button=form.querySelector('[type="submit"]');if(button){button.disabled=true;button.dataset.old=button.innerHTML;button.innerHTML='<span class="spinner-inline"></span> Processing…';}try{const fd=new FormData(form);
 if(form.classList.contains('gate-item')){const result=await request('/api/cases/'+form.dataset.case+'/gate','POST',{key:form.dataset.step,state:String(fd.get('state')),note:String(fd.get('note')||'')});toast('Private checklist step saved.');await render();return}
 if(form.id==='decision-form'){await request('/api/cases/'+form.dataset.case+'/decision','POST',{choice:String(fd.get('choice')),note:String(fd.get('note')||''),acknowledged:!!fd.get('acknowledged')});toast('Private decision saved.');await render();return}
 if(form.id==='offer-form'){state.draft={category:String(fd.get('category')),offer_text:String(fd.get('offer_text')),offer_url:String(fd.get('offer_url')||''),asking_price:String(fd.get('asking_price')||'')};if(state.draft.offer_text.trim().length<15)throw Error('Offer text must contain at least 15 characters.');navigate('/check/review')}
 if(form.id==='review-form'){if(!fd.get('consent'))throw Error('Consent is required.');state.draft.offer_text=String(fd.get('offer_text'));state.draft.redact=Boolean(fd.get('redact'));await submitOffer()}
 if(form.id==='invite-form'){const questions=fd.getAll('question').map(x=>String(x).trim());await createInvite(form.dataset.case,questions)}
 if(form.id==='seller-form'){const token=form.dataset.token;const answers=fd.getAll('answer').map(x=>String(x));await request('/api/proof/'+token+'/respond','POST',{answers,consent:!!fd.get('consent')});toast('Response submitted. Thank you for participating voluntarily.');navigate('/prove/'+token)}
 if(form.id==='admin-login'){await request('/api/admin/login','POST',{password:String(fd.get('password'))});toast('Local admin preview unlocked.');await render()}
 }catch(err){toast(err.message,'error')}finally{if(button?.isConnected){button.disabled=false;button.innerHTML=button.dataset.old||'Continue'}}});
window.addEventListener('popstate',render);
render();
